import re
import json
import time
from pathlib import Path
from typing import Optional, Dict, Any
from pydantic import BaseModel, Field

# Strict regex matching scholarship receipt IDs from the portal: SCH-XXXXXXXX (8 uppercase hex digits)
RECEIPT_ID_REGEX = re.compile(r"\b(SCH-[A-F0-9]{8})\b")


class InvalidReceiptError(Exception):
    """Raised when extracted receipt ID fails format validation."""
    pass


class ReceiptData(BaseModel):
    """Structured receipt output extracted directly from DOM text via regex (never generated by LLM)."""
    receipt_id: str = Field(description="Validated portal reference number, e.g. SCH-12345678")
    confirmation_title: str = Field(description="Confirmation title, e.g. Application received")
    receipt_url: str = Field(description="Full URL of the receipt page")
    extracted_at: float = Field(default_factory=time.time)
    applicant_name: Optional[str] = None
    course: Optional[str] = None
    college: Optional[str] = None
    metadata: Dict[str, Any] = Field(default_factory=dict)


class ReceiptExtractor:
    """
    Implements Receipt Extraction from Section 5 & 16 of the 48-Hour Playbook:
    - Extracts reference ID directly from DOM with regex.
    - Validates format strictly (rejection on failure).
    - NEVER allows the LLM to invent or hallucinate the receipt ID.
    - Serializes structured receipt JSON to disk.
    """

    def __init__(self, pattern: re.Pattern = RECEIPT_ID_REGEX):
        self.pattern = pattern

    def extract_from_html(
        self,
        html_content: str,
        current_url: str,
        applicant_name: Optional[str] = None,
        course: Optional[str] = None,
        college: Optional[str] = None
    ) -> ReceiptData:
        """
        Extracts and strictly validates receipt data from page HTML.
        """
        # 1. Regex search for reference number
        match = self.pattern.search(html_content)
        if not match:
            raise InvalidReceiptError(
                f"No valid receipt ID found in page content matching pattern '{self.pattern.pattern}'."
            )

        receipt_id = match.group(1).upper()

        # 2. Extract confirmation title
        title_match = re.search(r'<h1[^>]*>(.*?)</h1>', html_content, re.DOTALL | re.IGNORECASE)
        conf_title = "Application received"
        if title_match:
            conf_title = re.sub(r'<[^>]+>', '', title_match.group(1)).strip()

        return ReceiptData(
            receipt_id=receipt_id,
            confirmation_title=conf_title,
            receipt_url=current_url,
            applicant_name=applicant_name,
            course=course,
            college=college
        )

    def serialize_to_file(self, receipt: ReceiptData, output_path: Optional[Path] = None) -> Path:
        """Serializes ReceiptData to JSON file on disk."""
        if output_path is None:
            root = Path(__file__).resolve().parents[1]
            output_path = root / "data" / "receipt.json"

        output_path.parent.mkdir(parents=True, exist_ok=True)
        with open(output_path, "w", encoding="utf-8") as f:
            f.write(receipt.model_dump_json(indent=2))

        return output_path
